public class DateTimeZone_forOffsetHoursMinutes_TriageGen1Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // Test +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedOffset = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // Test -5:30
        // hoursOffset = -5, minutesOffset = 30
        // hoursInMinutes = -300
        // minutesOffset = -300 - abs(30) = -330
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        int expectedOffset = -330 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryMaxHours() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(23, 59);
        int expectedOffset = (23 * 60 + 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryMinHours() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-23, 59);
        int expectedOffset = (-23 * 60 - 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooLow() {
        DateTimeZone.forOffsetHoursMinutes(-24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(5, 60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesNegative() {
        // The logic forbids minutesOffset < 0 in the second if check
        DateTimeZone.forOffsetHoursMinutes(5, -1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_PositiveHoursNegativeMinutes() {
        // This triggers the specific check: if (hoursOffset > 0 && minutesOffset < 0)
        // Although minutesOffset < 0 is already caught by the previous check, 
        // we test to ensure coverage of the logic flow.
        DateTimeZone.forOffsetHoursMinutes(5, -1);
    }

    @Test
    public void testForOffsetHoursMinutes_ZeroHoursPositiveMinutes() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 30);
        int expectedOffset = 30 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_ZeroHoursNegativeMinutes() {
        // hoursOffset = 0, minutesOffset = 30 (wait, the code says if minutesOffset < 0 throw)
        // Let's check the logic: if (minutesOffset < 0 || minutesOffset > 59) throw.
        // To test the Math.abs branch for negative hours, we need hoursOffset < 0.
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-1, 0);
        int expectedOffset = -60 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }
}
